#!/usr/bin/env python3
"""Trust status of a codebase analysis: can another skill rely on it?

Works the status out from evidence on disk, never from a status someone typed:

  - the verification report's verdict (`verification-report.md`), its `major` corrections, and its
    re-check line ("After corrections: ... X of Y confirmed") when it has one
  - the analysis fingerprint the report recorded, compared with the pages now (any page changed
    since the verification makes the status STALE until the changed parts are verified)
  - the coverage gate, run now without writing anything (`coverage.py --report -`)
  - whether the code changed since the baseline (`ledger/baseline.json`, `delta.py`)
  - delta updates applied after the report (`delta-log.md`): their rewritten cards are unverified
  - per component (once discover.py wrote components.json): `ledger/components/NAME/verification-report.md`

  python3 -I <skill>/scripts/status.py --repo . --analysis codebase-analysis --check
  python3 -I <skill>/scripts/status.py --repo . --analysis codebase-analysis --write
  python3 -I <skill>/scripts/status.py --repo . --analysis codebase-analysis --fingerprint [--component NAME]

--check prints the status and its reasons and exits:
  0   VERIFIED: verified and current; rely on it
  10  STALE: verified, but out of date (the stale files and components are listed); refresh it first
  20  not verified (DRAFT, COMPONENTS_VERIFIED, or a failed or missing verification); do not rely on it
--write does the same work, writes `<analysis>/status.json`, and exits 0.
--fingerprint prints the fingerprint of the pages (or of one component's pages); the verifier
records it in its report's header as `| Analysis fingerprint | <value> |`.

Read-only on the repository; --check writes nothing at all. Standard library only.
"""

from __future__ import annotations

import argparse
import datetime
import hashlib
import json
import os
import re
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import inventory  # noqa: E402
import coverage  # noqa: E402
import components  # noqa: E402
import delta  # noqa: E402

HERE = os.path.dirname(os.path.abspath(__file__))
# The Verdict cell must hold exactly one verdict and nothing else (not the template's "PASS / ... / FAIL").
VERDICT = re.compile(r"^\|\s*Verdict\s*\|\s*\**\s*(PASS AFTER CORRECTIONS|PASS|FAIL)\s*\**\s*\|\s*$", re.M | re.I)
VERDICT_ROW = re.compile(r"^\|\s*Verdict\s*\|", re.M | re.I)
HIDDEN = re.compile(r"<!--.*?-->|^```.*?^```", re.S | re.M)
REPORT_DATE = re.compile(r"^\|\s*Date\s*\|\s*(\d{4}-\d{2}-\d{2}(?:[T ][\d:]+)?)", re.M)
FINGERPRINT_ROW = re.compile(r"^\|\s*Analysis fingerprint\s*\|\s*`?([0-9a-f]{16})`?", re.M | re.I)
RECHECK_LINE = re.compile(r"After corrections:[^\n]*?(\d+)\s+of\s+(\d+)\s+confirmed", re.I)
ACCURACY_ROW = re.compile(r"^\|\s*Accuracy[^|]*\|\s*(\d+(?:\.\d+)?)\s*%", re.M | re.I)
RECHECK_MIN_ACCURACY = 95.0  # a re-check judges a bounded list: only after a round as accurate as a PASS needs
REPORT_FILE = re.compile(r"^verification-report[\w.-]*\.md$")
RECHECK_OF_ROW = re.compile(r"^\|\s*Re-check of\s*\|\s*`?([^|`]+?)`?\s*\|\s*$", re.M | re.I)
PAGE_ROW = re.compile(r"^\|\s*`?([^|`]+?)`?\s*\|\s*`?([0-9a-f]{12})`?\s*\|\s*$", re.M)
CITES_LINE = re.compile(r"^<!--\s*cites\s+\S+@[0-9a-f]{40}\s*-->\s*$")
# Lines that change on every regeneration without changing any claim (knowledge.py's time stamps).
VOLATILE_LINE = re.compile(r'^\s*"generated":\s*"[^"]*",?\s*$|^Generated by `knowledge\.py` on ')
# Left out of the fingerprint: bookkeeping at the analysis root, and the ledger. Only at the root: a page
# deeper down with the same name (a module page for progress.py) is fingerprinted like any other page.
ROOT_EXCLUDED = {"revision-log.md", "run-notes.md", "progress.md", "delta-log.md", "CHANGELOG.md", "components.md",
                 "components.json", "status.json", ".gitattributes"}
EXIT = {"VERIFIED": 0, "STALE": 10}


def read(path):
    try:
        with open(path, encoding="utf-8", errors="replace") as handle:
            return handle.read()
    except OSError:
        return None


def fingerprint(analysis_abs, component=None):
    """16 hex characters over every file of the analysis, the knowledge graph included (`<!-- cites -->`
    lines and knowledge.py's time stamps left out), except the bookkeeping at the root (ROOT_EXCLUDED,
    verification-*) and ledger/. With a component: its pages only (lld/NAME/ and lld/api/NAME/)."""
    digest = hashlib.sha256()
    for rel, body in page_bodies(analysis_abs, component):
        digest.update(rel.encode() + b"\0" + body.encode("utf-8", "replace") + b"\0")
    return digest.hexdigest()[:16]


def page_fingerprints(analysis_abs, component=None):
    """{page: 12 hex characters} over the same pages and by the same rule as fingerprint(): the table a verifier
    records, so a re-check can find every page changed since, without source control."""
    return {rel: hashlib.sha256(body.encode("utf-8", "replace")).hexdigest()[:12] for rel, body in page_bodies(analysis_abs, component)}


def page_bodies(analysis_abs, component=None):
    """(page, text without cites lines and time stamps) of every fingerprinted page, in a fixed order."""
    prefixes = ("lld/%s/" % component, "lld/api/%s/" % component) if component else None
    for root, dirs, names in os.walk(analysis_abs):
        dirs[:] = sorted(d for d in dirs if not os.path.islink(os.path.join(root, d)))
        for name in sorted(names):
            full = os.path.join(root, name)
            rel = os.path.relpath(full, analysis_abs).replace(os.sep, "/")
            if os.path.islink(full) or name == ".DS_Store":
                continue
            if prefixes:
                if not rel.startswith(prefixes):
                    continue
            elif rel.startswith("ledger/") or rel in ROOT_EXCLUDED or ("/" not in rel and name.startswith("verification-")):
                continue
            try:
                with open(full, "rb") as handle:
                    raw = handle.read()
            except OSError:
                continue
            text = raw.decode("utf-8", "replace")
            body = "\n".join(l.rstrip() for l in text.splitlines()
                             if not CITES_LINE.match(l.strip()) and not VOLATILE_LINE.match(l)).strip()
            yield rel, body


def recorded_pages(report_text):
    """{page: hash} from a report's "## Page fingerprints" table (the (fingerprint) and (scope) rows included), or
    None when it has none."""
    table = section(report_text or "", "Page fingerprints")
    rows = dict(PAGE_ROW.findall(table)) if table else {}
    rows.update({"(%s)" % k: v for k, v in re.findall(r"^\|\s*\((fingerprint|scope)\)\s*\|\s*`?([^|`]+?)`?\s*\|\s*$", table, re.M)})
    return {k.strip(): v.strip() for k, v in rows.items() if k.strip().lower() != "page"} or None


def safe_report(analysis_abs, name):
    """The path of a report inside the analysis folder (its root or ledger/components/<name>/), or None."""
    clean = name.replace("\\", "/")
    if (os.path.isabs(name) or clean.startswith("/") or ":" in clean or ".." in clean.split("/") or not clean.endswith(".md")
            or ("/" in clean and not clean.startswith("ledger/components/"))):
        return None
    full = os.path.realpath(os.path.join(analysis_abs, clean))
    root = os.path.realpath(analysis_abs)
    return full if os.path.commonpath([full, root]) == root and os.path.isfile(full) else None


def base_accuracy(report_path, depth=0):
    """The lowest accuracy of the full round a re-check report builds on: its "Re-check of" row is followed (through
    earlier re-checks) to a report without one. Read there, not from the figures the re-check repeats (independent
    review: a row typed at 100% above the real one passed the bar). None when the chain is broken."""
    text = read(report_path)
    if text is None or depth > 20:
        return None
    visible = HIDDEN.sub("", text)
    if len(VERDICT.findall(visible)) != 1 or len(VERDICT_ROW.findall(visible)) != 1:
        return None  # only a real report (one verdict) can be a round
    found = [float(v) for v in ACCURACY_ROW.findall(section(visible, "Scores"))]
    own = min(found) if found else None
    base = RECHECK_OF_ROW.search(visible)
    if base and RECHECK_LINE.search(visible):
        name = base.group(1).strip()
        nxt = safe_report(os.path.dirname(report_path), name) if REPORT_FILE.match(os.path.basename(name)) else None
        older = base_accuracy(nxt, depth + 1) if nxt else None
        if older is None:
            return None  # a broken chain proves nothing
        return min(older, own) if own is not None else older  # never higher than any round on the way (third review)
    return own


def report_facts(path):
    """{verdict, date, majors, fingerprint, recheck} of a verification report, or None when there is none."""
    text = read(path)
    if text is None:
        return None
    visible = HIDDEN.sub("", text)  # a verdict inside a comment or a code block does not count
    verdicts = VERDICT.findall(visible)
    verdict = verdicts[0] if len(verdicts) == 1 and len(VERDICT_ROW.findall(visible)) == 1 else None
    date = REPORT_DATE.search(text)
    corrections = section(text, "Corrections")
    majors = sum(1 for line in corrections.splitlines() if line.lstrip().startswith("|") and re.search(r"\|\s*major\s*\|", line, re.I))
    printed = FINGERPRINT_ROW.search(visible)
    recheck = RECHECK_LINE.search(visible)
    accuracy = base_accuracy(path)  # the lowest Accuracy of this report and of every round its Re-check of row leads to
    chained = bool(RECHECK_OF_ROW.search(visible))
    noted = sum(1 for line in section(visible, "Noticed outside the re-check").splitlines()
                if line.lstrip().startswith("|") and not re.match(r"^\|\s*(#|-{3}|none\s*\|)", line.strip(), re.I))
    return {"accuracy": accuracy, "noted": noted, "chained": chained, "verdict": verdict.upper() if verdict else "UNREADABLE (the report needs exactly one Verdict row, holding one verdict)", "date": date.group(1) if date else "", "majors": majors,
            "fingerprint": printed.group(1) if printed else None,
            "recheck": (int(recheck.group(1)), int(recheck.group(2))) if recheck else None, "report": path}


def section(text, title):
    match = re.search(r"^##\s+%s\s*$" % re.escape(title), text, re.M)
    if not match:
        return ""
    rest = text[match.end():]
    nxt = re.search(r"^##\s", rest, re.M)
    return rest[:nxt.start()] if nxt else rest


def trusted(facts, current):
    """('ok'|'stale'|'no', reason) for one verification report against the pages' fingerprint now."""
    if facts is None:
        return "no", "no verification report"
    verdict = facts["verdict"]
    if verdict not in ("PASS", "PASS AFTER CORRECTIONS"):
        return "no", "verdict %s" % verdict
    if facts["majors"] and not (facts["recheck"] and facts["recheck"][0] == facts["recheck"][1]):
        return "no", "verdict %s with %d major corrections not re-checked: verify the corrected parts again" % (verdict, facts["majors"])
    open_items = ""
    if facts["recheck"] and (facts["recheck"][1] == 0 or facts["recheck"][0] < facts["recheck"][1]):
        if verdict != "PASS" or facts["majors"] or facts["recheck"][1] == 0:
            return "no", "after corrections only %d of %d flagged statements confirmed: correct and re-check the rest" % facts["recheck"]
        # A full round's PASS whose re-check of the earlier round is incomplete: the verdict table lets minor corrections
        # remain, and a PASS has no major one, so the earlier items not confirmed are minor and listed in this report
        # (live run, L22: a 97.5% PASS was refused because 5 of 15 earlier minor items were re-listed)
        open_items = "; %d of %d earlier corrections confirmed, the rest re-listed as minor corrections" % facts["recheck"]
    if verdict == "PASS AFTER CORRECTIONS" and not facts["recheck"]:
        return "no", "verdict PASS AFTER CORRECTIONS: apply the corrections, then have them re-checked"
    if facts["recheck"] and (facts.get("accuracy") is None or facts["accuracy"] < RECHECK_MIN_ACCURACY):
        # a re-check fixes the flagged statements, not the unsampled ones (independent review of the re-check rule):
        # it counts only after a round whose accuracy is a PASS's
        given = ("%.1f%%" % facts["accuracy"] if facts.get("accuracy") is not None else
                 "none: its `Re-check of` row does not lead to a verification report in this folder" if facts.get("chained")
                 else "none in its Scores")
        return "no", ("a re-check counts only after a round with accuracy of at least %.0f%% (the lowest on its chain: %s): "
                      "verify in full" % (RECHECK_MIN_ACCURACY, given))
    if not facts["fingerprint"]:
        return "no", "the report records no analysis fingerprint (`| Analysis fingerprint | ... |`): verify again with this version"
    if facts["fingerprint"] != current:
        return "stale", "pages changed since the verification (fingerprint %s then, %s now): verify the changed parts" % (facts["fingerprint"], current)
    recheck = ", after corrections %d of %d confirmed" % facts["recheck"] if facts["recheck"] else ""
    noted = "; %d minor item(s) noted outside the re-check, for the next full verification" % facts["noted"] if facts.get("noted") else ""
    if facts["recheck"] and not facts.get("chained") and verdict != "PASS":  # a full round's PASS is judged by its own rows
        noted += "; the re-check names no earlier round (no `Re-check of` row): judged by its own Accuracy rows"
    return "ok", "verdict %s%s; the pages are the ones verified (fingerprint %s)%s%s" % (verdict, recheck if not open_items else "",
                                                                                     current, open_items, noted)


def deltas_after(analysis_abs, when):
    """Rows of delta-log.md applied after the report date (a later day, or a later time when the report gives one)."""
    text = read(os.path.join(analysis_abs, "delta-log.md")) or ""
    if not when:
        return []
    rows = re.findall(r"^\|\s*(\d{4}-\d{2}-\d{2}T[\d:]+)\s*\|", text, re.M)
    if "T" not in when and " " not in when:
        return []  # a report with a date only: the fingerprint, not the day, says whether a delta changed the pages
    return [r for r in rows if r > when.replace(" ", "T")]


def evaluate(repo, analysis, depth, excludes):
    analysis_abs = os.path.join(repo, analysis)
    whole = report_facts(os.path.join(analysis_abs, "verification-report.md"))
    whole_state, whole_why = trusted(whole, fingerprint(analysis_abs))
    whole_ok = whole_state != "no"
    reasons, notes = [whole_why], []

    catalog = components.load_catalog(analysis_abs)
    rows = components.rows_of(catalog) if catalog and not catalog.get("proposed") else []
    comp_status = {}
    for name, _paths in rows:
        facts = report_facts(os.path.join(analysis_abs, "ledger", "components", name, "verification-report.md"))
        state, why = trusted(facts, fingerprint(analysis_abs, name))
        comp_status[name] = {"state": {"ok": "VERIFIED", "stale": "STALE"}.get(state, "UNVERIFIED" if facts is None else "NOT_VERIFIED"),
                             "verdict": facts["verdict"] if facts else "none", "why": why}

    drift = {"changed_files": 0, "files": [], "components": []}
    baseline_info = None
    work = delta.pending_work(repo, analysis, excludes)
    base_path = os.path.join(analysis_abs, "ledger", "baseline.json")
    if work is not None:
        base = delta.load_baseline(base_path)
        baseline_info = {"recorded": base.get("recorded", ""), "files": len(base.get("files", {}))}
        old = {p: e["sha"] for p, e in base.get("files", {}).items()}
        new = {p: e["sha"] for p, e in work["now"].items()}
        changed = sorted(p for p in set(old) | set(new) if old.get(p) != new.get(p))
        comp_of = components.component_map([{"path": p} for p in changed], rows) if rows else {}
        drift = {"changed_files": len(changed), "files": changed[:50],
                 "components": sorted({comp_of[p] for p in changed if p in comp_of})}
        open_work = len(work["items"]) + len(work["markers"]) + len(work["behind_pages"])
        if open_work:
            drift["open_delta_work"] = open_work

    gate = "NOT RUN"
    if whole_ok:
        late = deltas_after(analysis_abs, whole["date"])
        if baseline_info is None:
            status = "STALE"
            reasons.append("no baseline: cannot tell whether the code changed since; record one with delta.py --init")
        elif drift["changed_files"] or drift.get("open_delta_work"):
            status = "STALE"
            what = "%d files changed since the baseline" % drift["changed_files"] if drift["changed_files"] else "delta work is still open"
            reasons.append("%s%s: %s" % (what, " (components: %s)" % ", ".join(drift["components"]) if drift["components"] else "",
                                         ", ".join(drift["files"][:10]) or "see ledger/delta.md"))
            reasons.append("refresh first: tracking-codebase-changes (or delta.py --apply and next.py), then verify the changed parts")
        else:
            # The code is the baseline's: the gate must pass on the pages as they are now.
            run = subprocess.run([sys.executable, "-I", os.path.join(HERE, "coverage.py"), "--repo", repo, "--analysis", analysis,
                                  "--depth", depth, "--report", "-"] + sum((["--exclude", e] for e in excludes), []),
                                 capture_output=True, text=True)
            gate = "PASS" if run.returncode == 0 else "GAPS"
            if run.returncode != 0:
                status = "DRAFT"
                reasons.append("the coverage gate does not pass now at depth %s: %s" % (
                    depth, "; ".join(l.strip("- ").strip() for l in run.stdout.splitlines() if l.startswith("  - "))[:300]))
            elif whole_state == "stale":
                status = "STALE"
            elif late:
                status = "STALE"
                reasons.append("%d delta updates applied after the report (%s): the cards they rewrote are unverified; verify them" % (len(late), late[-1]))
            else:
                status = "VERIFIED"
                reasons.append("coverage gate PASS at depth %s now; code matches the baseline of %s" % (depth, baseline_info["recorded"]))
    else:
        if rows and comp_status and all(c["state"] == "VERIFIED" for c in comp_status.values()):
            status = "COMPONENTS_VERIFIED"
            reasons.append("every component is verified; the whole analysis is not yet" + (
                ": run the assemble step, then verify the whole analysis" if whole is None else " (see the reason above)"))
        else:
            status = "DRAFT"
            if rows:
                done = sum(c["state"] == "VERIFIED" for c in comp_status.values())
                reasons.append("%d of %d components verified" % (done, len(comp_status)))
    return {"schema": 1, "status": status, "gate": gate,
            "verification": {"verdict": whole["verdict"] if whole else "none", "date": whole["date"] if whole else "",
                             "major_corrections": whole["majors"] if whole else 0, "report": "verification-report.md" if whole else "",
                             "noted_outside_recheck": whole.get("noted", 0) if whole else 0},
            "baseline": baseline_info, "drift": drift, "components": comp_status,
            "reasons": reasons, "notes": notes, "checked": datetime.datetime.now().isoformat(timespec="seconds")}


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--repo", default=".")
    parser.add_argument("--analysis", default="codebase-analysis")
    parser.add_argument("--depth", choices=sorted(coverage.DEPTHS), default=None,
                        help="depth the gate is run at (default: components.json's depth, else deep)")
    parser.add_argument("--exclude", action="append", default=[])
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true", help="print the status; exit 0 verified, 10 stale, 20 not verified")
    mode.add_argument("--write", action="store_true", help="also write <analysis>/status.json; exit 0")
    mode.add_argument("--fingerprint", action="store_true", help="print the pages' fingerprint for a verification report")
    mode.add_argument("--page-fingerprints", action="store_true",
                      help="print the per-page table for a report's \"## Page fingerprints\" section")
    mode.add_argument("--pages-changed-since", metavar="REPORT",
                      help="list the pages changed since REPORT (a report in the analysis folder) recorded its page table")
    parser.add_argument("--component", default=None, help="with --fingerprint: one component's pages")
    args = parser.parse_args()

    repo = os.path.abspath(args.repo)
    analysis = args.analysis.replace("\\", "/").strip("/")
    if os.path.isabs(args.analysis) or ".." in analysis.split("/") or analysis in ("", "."):
        inventory.fail("--analysis must be a folder inside the repository, given relative to it")
    analysis_abs = os.path.join(repo, analysis)
    if not os.path.isdir(analysis_abs):
        print("UNVERIFIED: no analysis folder %s; run analyzing-a-codebase first" % analysis)
        sys.exit(20)
    if args.fingerprint:
        print(fingerprint(analysis_abs, args.component))
        return
    if args.page_fingerprints:
        print("| Page | Fingerprint |\n| --- | --- |")
        for page, digest in sorted(page_fingerprints(analysis_abs, args.component).items()):
            print("| `%s` | `%s` |" % (page, digest))
        # ties the table to the moment it was printed: --pages-changed-since refuses a table whose fingerprint is not
        # the report's own "Analysis fingerprint", or one recorded in another scope
        print("| (fingerprint) | `%s` |\n| (scope) | `%s` |" % (fingerprint(analysis_abs, args.component),
                                                            "component:" + args.component if args.component else "whole"))
        return
    if args.pages_changed_since:
        name = args.pages_changed_since
        path = safe_report(analysis_abs, name)
        if path is None:
            inventory.fail("--pages-changed-since takes a report file in the analysis folder, such as verification-report-2026-11-24.md")
        text = read(path)
        old = recorded_pages(text)
        if old is None:
            inventory.fail("%s has no \"## Page fingerprints\" table: the re-check cannot tell what changed; verify in full" % name)
        header = FINGERPRINT_ROW.search(HIDDEN.sub("", text or ""))
        scope = "component:" + args.component if args.component else "whole"
        if old.pop("(scope)", None) != scope:
            inventory.fail("%s's page table was not recorded for this scope (%s): verify in full" % (name, scope))
        if not header or old.pop("(fingerprint)", None) != header.group(1):
            inventory.fail("%s's page table does not belong to its Analysis fingerprint: it was printed at another time "
                           "or edited; verify in full" % name)
        now = page_fingerprints(analysis_abs, args.component)
        for page in sorted(set(old) | set(now)):
            if old.get(page) != now.get(page):
                print("%s %s" % ("added" if page not in old else "removed" if page not in now else "changed", page))
        return
    catalog = components.load_catalog(analysis_abs)
    depth = args.depth or (catalog or {}).get("depth") or "deep"
    result = evaluate(repo, analysis, depth, [e.strip("/") for e in args.exclude])
    label = {"VERIFIED": "VERIFIED", "STALE": "STALE"}.get(result["status"], "UNVERIFIED (%s)" % result["status"])
    print("%s: %s" % (label, analysis))
    for reason in result["reasons"]:
        print("  - " + reason)
    for note in result["notes"]:
        print("  note: " + note)
    if args.write:
        target = inventory.safe_target(repo, os.path.join(analysis_abs, "status.json"))
        with open(target, "w", encoding="utf-8") as handle:
            json.dump(result, handle, indent=1)
        print("wrote %s/status.json" % analysis)
        sys.exit(0)
    sys.exit(EXIT.get(result["status"], 20))


if __name__ == "__main__":
    main()
